   areas=["Moga town","Civil Lines","Dutt Road","GT Road","Kotkapura Road","Ferozepur Road","Amritsar Road","Dharamkot","Baghapurana","Nihal Singh Wala","Kot Ise Khan","Ajitwal","Badhni Kalan"],
